import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.BEUshCVJ.js";const d=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"zh/reference/faq.md","filePath":"zh/reference/faq.md","lastUpdated":1792880859000}'),i={name:"zh/reference/faq.md"};function n(s,e,l,h,c,u){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><p>常见问题的简短回答。遇到故障请从<a href="/meetcue/zh/troubleshooting/">排错总览</a>开始。</p><h2 id="subscription" tabindex="-1">MeetCue 需要订阅吗？ <a class="header-anchor" href="#subscription" aria-label="Permalink to &quot;MeetCue 需要订阅吗？ {#subscription}&quot;">​</a></h2><p>不需要。MeetCue 以 MIT 许可证免费开源。你用自己的密钥直接向语音和模型供应商按其正常价格付费。选择前设置里会显示每小时的预计费用，使用后会显示实际用量。</p><h2 id="cost" tabindex="-1">开一小时会要花多少钱？ <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;开一小时会要花多少钱？ {#cost}&quot;">​</a></h2><p>取决于你选的模型，差距可达数十倍。使用小模型的典型组合每小时几十美分，主要是语音识别费用。设置向导和 <strong>设置 › 供应商与费用</strong> 会按你的选择给出估算；也可以看<a href="/meetcue/zh/reference/pricing">价格参考</a>。</p><h2 id="visible" tabindex="-1">其他与会者能看到 MeetCue 吗？ <a class="header-anchor" href="#visible" aria-label="Permalink to &quot;其他与会者能看到 MeetCue 吗？ {#visible}&quot;">​</a></h2><p>默认情况下，屏幕共享和大多数录屏都看不到面板。部分录制方式和采集设备仍可能拍到，参见<a href="/meetcue/zh/troubleshooting/panel#screen-share">共享屏幕</a>。MeetCue 不会加入会议，也不会向会议软件发送任何内容。</p><h2 id="fairness" tabindex="-1">面试时使用 MeetCue 合适吗？ <a class="header-anchor" href="#fairness" aria-label="Permalink to &quot;面试时使用 MeetCue 合适吗？ {#fairness}&quot;">​</a></h2><p>这取决于你和具体场合。很多面试和考试不允许外部帮助，请遵守你认可的规则。练习模式就是为了让你在没有这些顾虑的情况下做准备。</p><h2 id="languages" tabindex="-1">支持哪些语言？ <a class="header-anchor" href="#languages" aria-label="Permalink to &quot;支持哪些语言？ {#languages}&quot;">​</a></h2><p>界面支持英文和简体中文。识别和提示支持中文和英文，包括一句话里中英混说。其他语言在支持它们的供应商上也许可用，但没有经过测试。</p><h2 id="platforms" tabindex="-1">能在 macOS 或 Linux 上用吗？ <a class="header-anchor" href="#platforms" aria-label="Permalink to &quot;能在 macOS 或 Linux 上用吗？ {#platforms}&quot;">​</a></h2><p>两个平台都能编译，但本版本只在 Windows 上完成了音频采集、面板行为和安装包。</p><h2 id="local-model" tabindex="-1">能用我自己电脑上运行的模型吗？ <a class="header-anchor" href="#local-model" aria-label="Permalink to &quot;能用我自己电脑上运行的模型吗？ {#local-model}&quot;">​</a></h2><p>可以，只要它提供支持流式输出的 OpenAI 兼容接口。在 <a href="/meetcue/zh/guide/providers#openai-compatible-apis">OpenAI 兼容接口</a>中填写它的 Base URL。语音识别仍需要使用支持的云服务之一。</p><h2 id="microphone" tabindex="-1">为什么 MeetCue 需要麦克风？ <a class="header-anchor" href="#microphone" aria-label="Permalink to &quot;为什么 MeetCue 需要麦克风？ {#microphone}&quot;">​</a></h2><p>用于判断你何时开始、何时结束回答，在你说话时把新问题排队，并为已讲到的要点打勾。如果只需要提示，可以关闭 <strong>跟踪已讲要点</strong>。</p>',18)])])}const f=a(i,[["render",n]]);export{d as __pageData,f as default};
